abstract class Reader4 {
    static String __file = ""; static int __pos = 0;
    int read4(char[] buf4) {
        int c = 0;
        while (c < 4 && __pos < __file.length()) buf4[c++] = __file.charAt(__pos++);
        return c;
    }
}

